values
  ('8a2b0eea-208e-52b3-af00-d118a9715ed7', null, (select id from public.skills where slug = 'write-g12-narrative-writing'), null, 'easy',
   $q$Which sentence would best replace sentence 17 as a conclusion that reflects on the experience?$q$, $q$[{"text":"Our class went to Miller Creek in October with kick nets and white plastic trays.","is_correct":false,"misconception_token":"restates-situation"},{"text":"The class results showed the creek was in good condition, and we wrote our lab reports.","is_correct":false,"misconception_token":"flat-ending-no-reflection"},{"text":"Walking back with numb feet, I kept picturing those three tails, proof the creek was alive.","is_correct":true},{"text":"Mayflies live for only a short time as adults, and some live for just a single day.","is_correct":false,"misconception_token":"generic-fact-ending"}]$q$::jsonb, $q$Walking back with numb feet, I kept picturing those three tails, proof the creek was alive.$q$, $q$The correct choice reflects on the meaning of the discovery and echoes the vivid detail in sentence 14. The choice ending "and we wrote our lab reports" adds an event but no reflection.$q$, 'draft', '45ab10b5-fea1-5c1f-9c7a-06ea5df02e70')
