  ('021036db-35ad-5b67-b6c7-033c0c8e9531', null, (select id from public.skills where slug = 'write-g12-sentence-structure'), null, 'medium',
   $q$Read the sentences: "Because the cave formations grow less than an inch per century. Visitors are asked not to touch them." Which revision fixes the fragment?$q$, $q$[{"text":"Because the cave formations grow less than an inch per century; visitors are asked not to touch them.","is_correct":false,"misconception_token":"semicolon-after-dependent-clause"},{"text":"Because the cave formations grow less than an inch per century, so visitors are asked not to touch them.","is_correct":false,"misconception_token":"redundant-conjunction"},{"text":"The cave formations grow less than an inch per century, visitors are asked not to touch them.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"Because the cave formations grow less than an inch per century, visitors are asked not to touch them.","is_correct":true}]$q$::jsonb, $q$Because the cave formations grow less than an inch per century, visitors are asked not to touch them.$q$, $q$An introductory dependent clause attaches to the main clause with a comma. Adding "so" after a "because" clause doubles the connector, and a semicolon cannot follow a dependent clause.$q$, 'draft', null)
