  ('c7012d42-6ffc-59f1-94df-6598f8bbda5b', null, (select id from public.skills where slug = 'write-g12-sentence-structure'), null, 'hard',
   $q$Read the sentence: "The committee reviewed every proposal for the new skate park, the one it chose, a design by two high school juniors, includes a ramp built from recycled concrete." Which statement best describes the sentence?$q$, $q$[{"text":"It is a comma splice; a period or semicolon is needed after \"skate park.\"","is_correct":true},{"text":"It is a comma splice; a semicolon is needed after \"it chose.\"","is_correct":false,"misconception_token":"wrong-boundary-located"},{"text":"It is a fragment because \"the one it chose\" contains no verb.","is_correct":false,"misconception_token":"misreads-relative-clause"},{"text":"It is correct because the appositive is properly set off by commas.","is_correct":false,"misconception_token":"appositive-masks-splice"}]$q$::jsonb, $q$It is a comma splice; a period or semicolon is needed after "skate park."$q$, $q$The first independent clause ends at "skate park," and a second one, "the one it chose ... includes a ramp," begins after it, so the comma there is a splice. A break after "it chose" would separate the subject "one" from its verb "includes."$q$, 'draft', null)
