  ('c6ca3dbd-077d-5c72-98e4-05acde8a12f7', null, (select id from public.skills where slug = 'write-g12-writing-with-evidence'), null, 'easy',
   $q$Which sentence should the writer delete because it does not support the analysis?$q$, $q$[{"text":"Sentence 11, because it admits a weakness in the reefs.","is_correct":false,"misconception_token":"avoids-counterclaim"},{"text":"Sentence 10, because the history of oyster harvests says nothing about erosion.","is_correct":true},{"text":"Sentence 9, because it explains evidence instead of adding new facts.","is_correct":false,"misconception_token":"removes-analysis"},{"text":"Sentence 6, because a quotation from Okafor repeats what the numbers already show.","is_correct":false,"misconception_token":"removes-key-evidence"}]$q$::jsonb, $q$Sentence 10, because the history of oyster harvests says nothing about erosion.$q$, $q$Sentence 10 is a historical fact about selling oysters and has no link to how well reefs protect the marsh. Sentence 11 should stay, because honestly noting the storm failure keeps the analysis accurate.$q$, 'draft', 'aa188600-a618-5070-b6ce-b986ea6b4591')
