  ('37292cf5-ee8d-5e73-8cde-d3719b2343c1', null, (select id from public.skills where slug = 'write-g12-writing-with-evidence'), null, 'easy',
   $q$Which revision of sentence 12 would best conclude the draft?$q$, $q$[{"text":"Book wagons were clearly the best way to bring reading to people in every rural place.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Fairweather lent about 600 books in her first year and more than 4,000 books a year by 1912.","is_correct":false,"misconception_token":"evidence-without-analysis"},{"text":"Many people today forget how hard it once was for farm families to find good books.","is_correct":false,"misconception_token":"off-topic-opinion"},{"text":"Baek's evidence shows that the wagon lasted because Fairweather built each visit around what families asked to read.","is_correct":true}]$q$::jsonb, $q$Baek's evidence shows that the wagon lasted because Fairweather built each visit around what families asked to read.$q$, $q$A strong conclusion returns to the claim in sentence 2 and connects it to the evidence about requests. The loan numbers alone repeat a detail without saying what it proves.$q$, 'draft', 'd95e0f64-caa6-5efb-83c0-0c458f6a3d65')
